[tikz]
\begin{tikzpicture}[scale=0.85]
\draw[gray!30,very thin,xstep=1,ystep=1] (0,0) grid (10,5);
\draw[->] (0,0)--(0,5.6);
\draw[->] (0,0)--(10.6,0);
\foreach \v/\p in {4/1,8/2,12/3,16/4,20/5} {\draw (-0.15,\p)--(0,\p); \node[left,font=\scriptsize] at (-0.15,\p) {$\v$};}
